  create(userId: string, courseId: string): Promise<Enrollment>;
}

// src/enrollments/enrollment.service.ts
@Injectable()
export class EnrollmentService {
  constructor(private readonly enrollments: EnrollmentRepository) {}
}

npm run start:

Error: Nest can't resolve dependencies of the EnrollmentService (?). Please make sure that the argument Object at index [0] is available in the EnrollmentModule context.

Statement: "Adding PgEnrollmentRepository, which implements EnrollmentRepository, to the providers array of EnrollmentModule fixes this error, because Nest matches the interface to the class that implements it."

